def autenticacao_obrigatoria(f):
    @wraps(f)
    def decorada(*args, **kwargs):
        token = request.headers.get('Authorization').split(' ')[1]
        try:
            g.usuario_atual = auth.verify_id_token(token)
        except Exception:
            return jsonify({'erro': 'token-expirado-ou-nao-autorizado'}), 401
        return f(*args, **kwargs)
    return decorada

def test_criar_produto_sem_token(app_cliente):
    resposta = app_cliente.post('/api/produtos', json={'nome': 'Notebook', 'preco': 5000})
    assert resposta.status_code == 401
